#include "ScalarConverter.hpp"
#include "Log.hpp"

void	test(std::string literal)
{
	Log::out("literal string: \"", YELLOW);
	Log::out(literal, YELLOW);
	Log::nl("\"", YELLOW);
	ScalarConverter::convert(literal);
}

int	main()
{
	Log::nl("Caracter", CYAN);
	test("a");
	test("K");
	test(".");
	test("`");
	Log::nl();

	Log::nl("Int", CYAN);
	test("0");
	test("+97");
	test("255");
	test("256");
	test("-200");
	test("-124319");
	test("2147483647");
	test("-2147483648");
	Log::nl();

	Log::nl("Float", CYAN);
	test("1.0f");
	test("+97.123f");
	test("124319.1234567891234f");
	test("-124319.1234567891234f");
	test("340000000000000000000000000000000000000.123f");
	test("-340000000000000000000000000000000000000.123f");
	Log::nl();

	Log::nl("PseudoFloat", CYAN);
	test("+inff");
	test("-inff");
	test("nanf");
	Log::nl();

	Log::nl("Double", CYAN);
	test("1.0");
	test("+97.123");
	test("124319.1111111111111111111111");
	test("-124319.0");
	test(".123");
	Log::nl();

	Log::nl("PseudoDouble", CYAN);
	test("+inf");
	test("-inf");
	test("nan");
	Log::nl();

	Log::nl("Non of above", CYAN);
	Log::nl("Empty", CYAN);
	test("");
	Log::nl("Overflow", CYAN);
	test("2147483648");
	test("-2147483649");
	test("350000000000000000000000000000000000000.123f");
	test("-350000000000000000000000000000000000000.123f");
	test(".123");
	Log::nl("Invalid format", CYAN);
	test("123abc");
	test("123 123");
	test("0123");
	test("012.3");
	test("0.");
	test("0.123ff");
	test("0.123F");
	test("0.123.123");
	test("inff");
	test("nanff");
}
